const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (input) => {
    const s = input;
    const qq = "QAQ";
    const arr = Array.from({ length: s.length + 1 }, () => Array(4).fill(-1));

    function Q(m, n) {
        if (arr[n][m] !== -1)
            return arr[n][m];
        if (m === 0)
            return 1;
        if (n === 0)
            return 0;
        let i = 0, j = 0;
        if (qq[m - 1] === s[n - 1])
            i = Q(m - 1, n - 1);
        j = Q(m, n - 1);
        arr[n][m] = i + j;
        return i + j;
    }

    console.log(Q(3, s.length));
    rl.close();
});

